    public function recordCompanyProviderReversal($issuer,$actor,\CompanyReceiptReversalSource $source):string
    {
        $issuer=\IssuerPolicy::id($issuer);$actor=\IssuerPolicy::id($actor);$p=db_prefix();if(get_class($source)!=='BancoBrasil\\ReviewedExternalReversal')throw new \DomainException('company_reversal_source_denied');$source->assertSchema($this->db,$p);$reversals=new \CompanyBankReceiptReversals($this->db,$p);$balanceReader=new \CompanyInvoiceBalance($this->db,$p);$journal=new \CompanyFinancialJournal($this->db,$p);$tables=array_values(array_unique(array_merge($source->tables(),$reversals->tables(),$balanceReader->tables(),(new \CompanyCurrencyUnits($this->db,$p))->tables(),$journal->tables('payment'),['modules'])));
        return \IssuerTransaction::run($this->db,$p,$tables,function()use($issuer,$actor,$p,$source,$reversals,$balanceReader,$journal):string{
            $acl=new \IssuerResourceAccess($this->db,$p);$acl->lockFinancialIdentity($issuer,$actor);if(!$acl->can($issuer,$actor,'payments','delete')||!$acl->can($issuer,$actor,'invoices','view'))throw new \DomainException('company_bank_reversal_access_denied');$claim=$source->claim($this->db,$p,$issuer,$actor);if(array_diff(array_keys($claim),['invoice','payment','key','original','reversal'])||!(($claim['original']??null) instanceof \CompanyBankComponentsData)||!(($claim['reversal']??null) instanceof \CompanyBankReversalData)||!is_string($claim['key']??null)||!preg_match('/^[a-f0-9]{64}$/D',$claim['key']))throw new \DomainException('company_bank_reversal_invalid');$invoice=\IssuerPolicy::id($claim['invoice']);$payment=\IssuerPolicy::id($claim['payment']);$key=$claim['key'];$dto=$claim['reversal'];$original=$claim['original'];$data=$dto->data();$expectedKey=hash('sha256',json_encode(['bb-full-external-reversal',$issuer,$payment,$data['original_receipt_key']],JSON_THROW_ON_ERROR));if(!hash_equals($key,$expectedKey))throw new \DomainException('company_bank_reversal_invalid');if(!hash_equals($data['original_components_hash'],$original->fingerprint()))throw new \DomainException('company_bank_reversal_original_review');
