        $reversals=new \CompanyBankReceiptReversals($this->db,$p);$balanceReader=new \CompanyInvoiceBalance($this->db,$p);$journal=new \CompanyFinancialJournal($this->db,$p);\IssuerTransaction::assertOwned($this->db,$p,array_values(array_unique(array_merge($reversals->tables(),$balanceReader->tables(),(new \CompanyCurrencyUnits($this->db,$p))->tables(),$journal->tables('payment')))));$acl=new \IssuerResourceAccess($this->db,$p);$acl->lockFinancialIdentity($issuer,$actor);if(!$acl->can($issuer,$actor,'payments','delete')||!$acl->can($issuer,$actor,'invoices','view'))throw new \DomainException('company_bank_reversal_access_denied');$data=$dto->data();$expectedKey=hash('sha256',json_encode(['bb-full-external-reversal',$issuer,$payment,$data['original_receipt_key']],JSON_THROW_ON_ERROR));if(!hash_equals($key,$expectedKey))throw new \DomainException('company_bank_reversal_invalid');if(!hash_equals($data['original_components_hash'],$original->fingerprint()))throw new \DomainException('company_bank_reversal_original_review');
            $captured=$reversals->capturedInOwned($issuer,$actor,$invoice,$payment);if($captured){if(!hash_equals($captured->fingerprint(),$dto->fingerprint()))throw new \DomainException('company_bank_reversal_receipt_conflict');return ['key'=>$key,'new'=>false];}
